#include <stdio.h>
#include <string.h>

char findTheDifference(const char *s, const char *t) {
    unsigned char ans = 0;
    for (int i = 0; s[i] != '\0'; ++i) ans ^= (unsigned char)s[i];
    for (int i = 0; t[i] != '\0'; ++i) ans ^= (unsigned char)t[i];
    return (char)ans;
}

static int read_string(const char *line, int *pos, char *out, int cap) {
    int n = (int)strlen(line);
    while (*pos < n && line[*pos] != '"') ++(*pos);
    if (*pos >= n) return 0;
    ++(*pos);
    int k = 0;
    while (*pos < n && line[*pos] != '"') {
        if (k + 1 < cap) out[k++] = line[*pos];
        ++(*pos);
    }
    if (*pos >= n) return 0;
    out[k] = '\0';
    ++(*pos);
    return 1;
}

